#include <bits/stdc++.h>
using namespace std;

const int MAXN = (1 << 19) | 5;
int n, k, p, maxn, count_bits[MAXN], f_vals[MAXN];
int tmp1_tmp[20][MAXN], tmp2_tmp[20][MAXN], tmp3_tmp[20][MAXN];
long long total_pow;
long long trans[20][MAXN];
long long fact_arr[MAXN], inv_fact_arr[MAXN];

long long power(long long base, long long exp) {
    long long res = 1, cur = base;
    while (exp > 0) {
        if (exp & 1) res = res * cur % p;
        cur = cur * cur % p;
        exp >>= 1;
    }
    return res;
}

void setup() {
    fact_arr[0] = 1;
    for (int i = 1; i <= maxn; i++)
        fact_arr[i] = fact_arr[i - 1] * i % p;
    inv_fact_arr[maxn] = power(fact_arr[maxn], p - 2);
    for (int i = maxn - 1; i >= 0; i--)
        inv_fact_arr[i] = inv_fact_arr[i + 1] * (i + 1) % p;
}

int get_lower_power(int x) {
    int res = 1;
    while (res < x) res <<= 1;
    return res;
}

void FWT(int *arr, int len, bool inv = false) {
    long long *temp = trans[0];
    for (int i = 0; i < len; i++) temp[i] = arr[i];
    for (int step = 1; step < len; step <<= 1) {
        for (int j = 0; j < len; j += (step << 1)) {
            for (int k = j; k < j + step; k++) {
                long long val = temp[k];
                if (inv) {
                    temp[k + step] -= val;
                } else {
                    temp[k + step] += val;
                }
            }
        }
    }
    for (int i = 0; i < len; i++) {
        arr[i] = (int)(temp[i] % p);
        if (arr[i] < 0) arr[i] += p;
    }
}

inline void mod_adjust(long long &x) { if (x >= total_pow) x -= total_pow; }

void do_multiply() {
    memset(tmp1_tmp, 0, sizeof tmp1_tmp);
    memset(trans, 0, sizeof trans);
    for (int i = 0; i <= maxn; i++)
        tmp1_tmp[count_bits[i]][i] = f_vals[i];
    for (int j = 0; j <= 19; j++)
        FWT(tmp1_tmp[j], maxn + 1);
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= maxn; s++)
                mod_adjust(trans[q + l][s] += 1LL * tmp1_tmp[q][s] * tmp2_tmp[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= maxn; s++)
            tmp3_tmp[q][s] = (int)(trans[q][s] % p);
    for (int j = 0; j <= 19; j++)
        FWT(tmp3_tmp[j], maxn + 1, true);
    for (int j = 0; j <= maxn; j++)
        f_vals[j] = tmp3_tmp[count_bits[j]][j];
}

void do_alt_multiply() {
    static int temp[20][MAXN];
    for (int i = 0; i <= 19; i++)
        memset(trans[i], 0, sizeof(long long) * (maxn + 1));
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= maxn; s++)
                mod_adjust(trans[q + l][s] += 1LL * tmp2_tmp[q][s] * tmp2_tmp[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= maxn; s++)
            temp[q][s] = (int)(trans[q][s] % p);
    for (int i = 0; i <= 19; i++)
        FWT(temp[i], maxn + 1, true);
    for (int i = 0; i <= 19; i++)
        memset(tmp2_tmp[i], 0, sizeof(int) * (maxn + 1));
    for (int i = 0; i <= maxn; i++)
        tmp2_tmp[count_bits[i]][i] = temp[count_bits[i]][i];
    for (int i = 0; i <= 19; i++)
        FWT(tmp2_tmp[i], maxn + 1);
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    total_pow = 1LL * p * p;
    if (n & 1) {
        printf("%lld", power(k, n));
        return 0;
    }
    f_vals[0] = 1;
    maxn = get_lower_power(n + 1) - 1;
    setup();
    for (int i = 0; i <= maxn; i++)
        count_bits[i] = __builtin_popcount(i);
    for (int i = 0; i <= maxn; i++)
        tmp2_tmp[count_bits[i]][i] = inv_fact[i];
    for (int i = 0; i <= 19; i++)
        FWT(tmp2_tmp[i], maxn + 1);
    int res_k = k;
    while (res_k) {
        if (res_k & 1) do_multiply();
        res_k >>= 1;
        if (res_k) do_alt_multiply();
    }
    printf("%lld", (power(k, n) - fact_arr[n] * f_vals[n] % p + p) % p);
    return 0;
}
